"""Export one Agent preset, declared code and resources as a wheel project."""

from __future__ import annotations

import argparse
import json
import shutil
from collections.abc import Sequence
from glob import escape
from pathlib import Path

from roborsi.agents.config import AgentConfig, bundle_package


def export_agent(
    config: str | Path,
    destination: str | Path,
    *,
    name: str,
    overrides: Sequence[str] = (),
) -> Path:
    """Create a new, relocatable setuptools project for ``bundle:name``.

    Only inputs explicitly referenced by the preset and package initializers
    are copied. The resulting ``src/`` also works with AgentArtifactStore.
    No custom Agent factory or simulator is imported while exporting.
    """
    package = bundle_package(f"bundle:{name}")
    preset = AgentConfig.load(config, overrides=overrides)
    output = Path(destination).resolve()
    if output.is_relative_to(preset.source_root):
        raise ValueError("Agent export directory must be outside source_root")
    output.mkdir(parents=True, exist_ok=False)
    try:
        directory = output / "src" / package
        payload = directory / "payload"
        for source in preset.input_files:
            target = payload / source.relative_to(preset.source_root)
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, target)
        relative = preset.path.relative_to(preset.source_root).as_posix()
        exported = AgentConfig.from_file(payload / relative, overrides=preset.overrides)
        if (
            exported.source_root != payload
            or exported.fingerprint != preset.fingerprint
        ):
            raise ValueError(
                "Agent config is not relocatable; use relative paths and source_root"
            )
        preset.verify()
        module, _, _ = preset.factory.partition(":")
        if not module.startswith("roborsi.") and not any(
            (payload / path).is_file()
            for path in (
                module.replace(".", "/") + ".py",
                module.replace(".", "/") + "/__init__.py",
            )
        ):
            raise ValueError("Agent factory module must be declared in config.code")
        manifest = {
            "schema_version": 1,
            "name": name,
            "config": relative,
            "config_sha256": preset.fingerprint,
            "factory": f"{package}:make_agent",
            "overrides": list(preset.overrides),
            "files": [
                path.relative_to(preset.source_root).as_posix()
                for path in preset.input_files
            ],
        }
        (directory / "manifest.json").write_text(json.dumps(manifest, indent=2) + "\n")
        (directory / "__init__.py").write_text(
            '"""Installed RoboRSI Agent preset. Generated by roborsi.agents.package."""\n'
            "\ndef make_agent(case_dir):\n"
            "    from roborsi.agents.config import AgentConfig\n"
            f"    return AgentConfig.load('bundle:{name}').create_agent(case_dir)\n"
        )
        dependencies = ["roborsi", *preset.document.get("dependencies", [])]
        package_data = [
            "manifest.json",
            *(escape(f"payload/{name}") for name in manifest["files"]),
        ]
        (output / "pyproject.toml").write_text(
            '[build-system]\nrequires = ["setuptools>=68", "wheel"]\nbuild-backend = "setuptools.build_meta"\n'
            "\n[project]\n"
            f"name = {json.dumps(package.replace('_', '-'))}\n"
            f'version = "0.0.0+{preset.fingerprint[:16]}"\n'
            'requires-python = ">=3.10,<3.13"\n'
            f"dependencies = {json.dumps(dependencies)}\n"
            '\n[tool.setuptools]\npackage-dir = {"" = "src"}\n'
            f"packages = [{json.dumps(package)}]\n"
            "\n[tool.setuptools.package-data]\n"
            f"{json.dumps(package)} = {json.dumps(package_data)}\n"
        )
        (output / "requirements.in").write_text("\n".join(dependencies) + "\n")
        (output / "source.json").write_text(json.dumps(manifest, indent=2) + "\n")
        return output
    except BaseException:
        shutil.rmtree(output)
        raise


def main() -> None:
    """Export a preset without installing dependencies or contacting a model."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--config", required=True, help="Agent preset path or bundle:name"
    )
    parser.add_argument("--name", required=True, help="unique lowercase bundle name")
    parser.add_argument(
        "--set",
        action="append",
        default=[],
        help="PATH=JSON preset override; repeat as needed",
    )
    parser.add_argument(
        "--output", required=True, type=Path, help="new directory outside source_root"
    )
    args = parser.parse_args()
    try:
        output = export_agent(
            args.config, args.output, name=args.name, overrides=args.set
        )
    except (ValueError, OSError, ImportError) as exc:
        parser.error(str(exc))
    print(output)


if __name__ == "__main__":
    main()
